  `status` int DEFAULT NULL COMMENT '设备状态：1=停用 2=离线，3=在线',
  `e_status` int DEFAULT NULL COMMENT '故障状态：1=告警，2=正常',
  `s_status` int DEFAULT NULL COMMENT '库存状态：1=缺货，2=正常',
  `del_status` int DEFAULT NULL COMMENT '删除标识：1=正常 2=删除',
  `run_time` int DEFAULT '0' COMMENT '设备通电开机的累计时间（不管泵是否工作），单位：小时',
  `create_user_id` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_user_id` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `fault_cause` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '故障原因',
  `fault_time` datetime DEFAULT NULL COMMENT '故障时间',
  `recovery_time` datetime DEFAULT NULL COMMENT '故障恢复时间',
  `fault_type` int DEFAULT NULL COMMENT '故障类型',
  `province_code` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '省code',
  `province_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '省名称',
  `city_code` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '城市code',
  `city_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '城市名称',
  `district_code` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区code',
  `district_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区名称',
  `address` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地址',
  `lng` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '经度值',
  `lat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纬度值',
  `biz_user_id` bigint DEFAULT NULL COMMENT '业务员用户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=100091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备信息表';
