--
-- Table structure for table `t_device_oil_detail`
--

DROP TABLE IF EXISTS `t_device_oil_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_device_oil_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `oil_type_id` bigint DEFAULT NULL COMMENT '油品类型id',
  `device_oil_id` bigint DEFAULT NULL COMMENT '表t_device_oil主键',
  `fill_mode` int DEFAULT NULL COMMENT '加注模式',
  `water` decimal(18,2) DEFAULT NULL COMMENT '水液配比：水值',
  `oil` decimal(18,2) DEFAULT NULL COMMENT '水液配比：油值',
  `oil_set` decimal(18,2) DEFAULT NULL COMMENT '油加设量',
  `upper_set` decimal(18,2) DEFAULT NULL COMMENT '液位上限',
  `lower_set` decimal(18,2) DEFAULT NULL COMMENT '液位下限',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '操作员(v2.0作废)',
  `status` int DEFAULT NULL COMMENT '1=正常 2=注销',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime DEFAULT NULL COMMENT '修改时间',
  `modify_user_id` bigint DEFAULT NULL,
  `biz_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备端id',
  `biz_creator` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备端创建人',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号，用于比较设备端与云端数据版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100156 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备加注模式配置';
/*!40101 SET character_set_client = @saved_cs_client */;

