--
-- Table structure for table `t_device_oil_log`
--

DROP TABLE IF EXISTS `t_device_oil_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_device_oil_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `oil_type_id` bigint DEFAULT NULL COMMENT '油品类型id',
  `avai_oil` decimal(18,2) DEFAULT NULL COMMENT '剩余油量，保留1位小数',
  `avai_ratio` decimal(18,2) DEFAULT NULL COMMENT '剩余油量比例，保留1位小数，不含%号，如58.8%则为58.8',
  `avai_short` decimal(18,2) DEFAULT NULL COMMENT '近程液位，保留1位小数',
  `rate_short` decimal(18,2) DEFAULT NULL COMMENT '近程液位比例，保留1位小数，不含%号，如58.8%则为58.8',
  `avai_long` decimal(18,2) DEFAULT NULL COMMENT '远程液位，保留1位小数',
  `rate_long` decimal(18,2) DEFAULT NULL COMMENT '远程液位比例，保留1位小数，不含%号，如58.8%则为58.8',
  `modify_type` int NOT NULL DEFAULT '0' COMMENT '更新类型：0=订单上报更新、1=设备上报更新、3=设备上报油品更新',
  `status` int DEFAULT NULL COMMENT '1=正常 2=注销',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime DEFAULT NULL COMMENT '修改时间',
  `modify_user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4066 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备库存液位变更历史';
/*!40101 SET character_set_client = @saved_cs_client */;

