--
-- Table structure for table `t_device_oil_order`
--

DROP TABLE IF EXISTS `t_device_oil_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_device_oil_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `oil_type_id` bigint DEFAULT NULL COMMENT '油品类型id',
  `water` decimal(18,2) DEFAULT NULL COMMENT '水油比：水值',
  `oil` decimal(18,2) DEFAULT NULL COMMENT '水油比：油值',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作员',
  `order_time` datetime DEFAULT NULL COMMENT '加注时间',
  `water_val` decimal(18,2) DEFAULT NULL COMMENT '水加注值',
  `oil_val` decimal(18,2) DEFAULT NULL COMMENT '油加注值',
  `total_oil` decimal(18,2) DEFAULT NULL COMMENT '总量',
  `avai_oil` decimal(18,2) DEFAULT NULL COMMENT '剩余量',
  `status` int DEFAULT NULL COMMENT '1=正常 2=注销',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime DEFAULT NULL COMMENT '修改时间',
  `is_settlement` int DEFAULT NULL COMMENT '是否结算1=待结算 2=待生效 3=已结算',
  `batch_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结算批次号',
