--
-- Table structure for table `t_device_param`
--

DROP TABLE IF EXISTS `t_device_param`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_device_param` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `remote_tank` decimal(18,2) DEFAULT NULL COMMENT '远程灌液位，保留1位小数',
  `near_tank` decimal(18,2) DEFAULT NULL COMMENT '近程罐液位，保留1位小数',
  `original_tank` decimal(18,2) DEFAULT NULL COMMENT '原液灌液位，保留1位小数',
  `oil_flow_meter` decimal(18,2) DEFAULT NULL COMMENT '油流量记脉冲调节，保留1位小数',
  `water_flow_meter` decimal(18,2) DEFAULT NULL COMMENT '水流量记脉冲调节，保留1位小数',
  `water_warn_value` decimal(18,2) DEFAULT NULL COMMENT '水流量告警设置值，保留1位小数',
  `oil_warn_value` decimal(18,2) DEFAULT NULL COMMENT '油流量告警设置值',
  `status` int DEFAULT NULL COMMENT '1=正常 2=注销',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime DEFAULT NULL COMMENT '修改时间',
  `modify_user_id` bigint DEFAULT NULL,
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '设备端id',
