DROP TABLE IF EXISTS `t_file`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_file` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `file_name` varchar(128) DEFAULT NULL COMMENT '文件名',
  `file_type` varchar(45) DEFAULT NULL COMMENT '文件类型',
  `file_suffix` varchar(45) DEFAULT NULL COMMENT '文件后缀',
  `file_size` decimal(18,2) DEFAULT NULL,
  `channel` int DEFAULT NULL COMMENT '上传渠道 1=阿里oss 2=七牛',
  `file_host` varchar(64) DEFAULT NULL,
  `file_url` varchar(512) DEFAULT NULL,
  `status` int DEFAULT NULL COMMENT '1=可用 2=注销',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `IDX_FILE_URL` (`file_url`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=100287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='附件';
/*!40101 SET character_set_client = @saved_cs_client */;

