/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_msg` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type` int DEFAULT NULL COMMENT '消息类型：1=故障通知 2=库存通知 3=系统通知',
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '消息标题',
  `content` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '消息内容',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户名称',
  `biz_time` datetime DEFAULT NULL COMMENT '业务时间',
  `status` int DEFAULT NULL COMMENT '是否已读 1=未读 2=已读',
  `create_time` datetime DEFAULT NULL,
  `biz_type` int DEFAULT NULL COMMENT '1=故障 2=30%库存 3=20%库存 4=10%库存',
  `ext_json` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '扩展字段',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=103095 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='消息';
/*!40101 SET character_set_client = @saved_cs_client */;

