DROP TABLE IF EXISTS `t_oil_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_oil_type` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint DEFAULT NULL COMMENT '设备ID',
  `customer_id` bigint DEFAULT NULL COMMENT '客户id',
  `oil_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '油品名称',
  `oil_model` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '油品型号',
  `status` int DEFAULT NULL COMMENT '1=正常 2=删除',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间（设备上报时的设备端时间）',
  `create_operator` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL,
  `update_operator` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL,
  `biz_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备端id：设备激活码_业务id',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号，用于比较设备端与云端数据版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100202 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户油品信息维护（设备端同步）';
/*!40101 SET character_set_client = @saved_cs_client */;

