--
-- Table structure for table `t_settlement`
--

DROP TABLE IF EXISTS `t_settlement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_settlement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
  `total_count` decimal(18,2) DEFAULT NULL COMMENT '油总量',
  `status` int DEFAULT NULL COMMENT '2=待客户确认 3=已结算 4=客户已确认',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结算单号',
  `start_date` datetime DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `create_user_id` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `update_user_id` bigint DEFAULT NULL,
  `is_share` int DEFAULT NULL COMMENT '是否分享',
  `device_id` bigint DEFAULT NULL COMMENT '设置ID',
  `oil_type_id` bigint DEFAULT NULL COMMENT '油品ID',
  `confirm_user_id` bigint DEFAULT NULL COMMENT '客户确认人id',
  `confirm_time` datetime DEFAULT NULL COMMENT '客户确认时间',
  `customer_user_id` bigint DEFAULT NULL COMMENT '客户确认人ID',
  `customer_time` datetime DEFAULT NULL COMMENT '客户确认时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100061 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='结算表';
/*!40101 SET character_set_client = @saved_cs_client */;

