/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `login_name` varchar(30) NOT NULL COMMENT '登录账号',
  `user_name` varchar(30) DEFAULT NULL COMMENT '用户昵称',
  `sys_user_type` int DEFAULT '1' COMMENT '用户类型：1=平台用户，2=客户用户',
  `email` varchar(50) DEFAULT '' COMMENT '用户邮箱',
  `phone_number` varchar(11) DEFAULT '' COMMENT '手机号码',
  `sex` int DEFAULT '0' COMMENT '用户性别（0男 1女 2未知）',
  `avatar` varchar(2048) DEFAULT '' COMMENT '头像路径',
  `password` varchar(50) DEFAULT '' COMMENT '密码',
  `salt` varchar(20) DEFAULT '' COMMENT '盐加密',
  `status` int DEFAULT '0' COMMENT '帐号状态（1正常 2停用）',
  `del_flag` int DEFAULT '0' COMMENT '删除标志（1代表存在 2代表删除）',
  `login_ip` varchar(128) DEFAULT '' COMMENT '最后登录IP',
  `login_date` datetime DEFAULT NULL COMMENT '最后登录时间',
  `pwd_update_date` datetime DEFAULT NULL COMMENT '密码最后更新时间',
  `create_userId` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_userId` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `user_id` bigint DEFAULT NULL COMMENT '保留，用户ID(当和小程序用户存在关联时)',
  `permission` int DEFAULT NULL COMMENT '登录权限：1=所有 2=可登录后台 3=可登录小程序',
  `role` int DEFAULT '2' COMMENT '平台角色： 2=管理员 3=业务员；客户角色：12=管理员 13=普通用户',
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX_LOGIN_NAME` (`login_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1000115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户信息表';
