/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_third_auth` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `open_id` varchar(64) DEFAULT NULL,
  `union_id` varchar(64) DEFAULT NULL,
  `third_type` varchar(45) DEFAULT NULL COMMENT '1=微信 2=支付宝 3=抖音',
  `user_id` bigint DEFAULT NULL COMMENT '会员id',
  `nick_name` varchar(128) DEFAULT NULL,
  `avatar_url` varchar(256) DEFAULT NULL COMMENT '头像',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `biz_type` int DEFAULT NULL COMMENT '1=运营小程序 2=客户端 3=公众号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=228 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='第三方授权认证表';
