--
-- Table structure for table `t_transaction`
--

DROP TABLE IF EXISTS `t_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_transaction` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `t_id` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '事务ID',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID',
  `biz_type` int DEFAULT NULL COMMENT '业务类型：2=更新工作模式配置；3=查询日志目录；4=上传日志；5=删除日志',
  `biz_data` varchar(2000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务数据',
  `status` int DEFAULT NULL COMMENT '1=正常 2=注销',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime DEFAULT NULL COMMENT '修改时间',
  `modify_user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100329 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='事务';
/*!40101 SET character_set_client = @saved_cs_client */;

