--
-- Table structure for table `t_user`
--

DROP TABLE IF EXISTS `t_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `real_name` varchar(45) DEFAULT NULL COMMENT '真实姓名',
  `gender` int DEFAULT NULL COMMENT '1=男 2=女',
  `birth_day` datetime DEFAULT NULL COMMENT '出生日期',
  `province` varchar(128) DEFAULT NULL COMMENT '省份',
  `city` varchar(128) DEFAULT NULL COMMENT '城市',
  `district` varchar(128) DEFAULT NULL COMMENT '区',
